def normalize(s):
    s = s.strip().lower()
    return s[:-1] if s.endswith(".") else s


def run_eval(variants, dataset, call_model):
    if not dataset:
        raise ValueError("empty dataset")
    report = {}
    for name, template in variants.items():
        failures = []
        for case in dataset:
            out = call_model(template.format(text=case["text"]))
            if normalize(out) != normalize(case["label"]):
                failures.append({"input": case["text"], "expected": case["label"], "got": out})
        acc = 1 - len(failures) / len(dataset)
        report[name] = {"accuracy": acc, "failures": failures}
    return report


def mock_model(prompt):
    # pretends v2 (which lists the labels) is better on negatives
    text = prompt.rsplit("Text:", 1)[1].lower()
    if "refund" in text or "broken" in text:
        return "Negative." if "Labels:" in prompt else "neutral"
    return " Positive"


if __name__ == "__main__":
    data = [{"text": "love it", "label": "positive"},
            {"text": "broken on arrival", "label": "negative"},
            {"text": "want a refund", "label": "negative"}]
    variants = {"v1": "Classify sentiment. Text: {text}",
                "v2": "Labels: positive, negative, neutral. Answer with one label. Text: {text}"}
    for name, r in run_eval(variants, data, mock_model).items():
        print(name, round(r["accuracy"], 2), r["failures"])

from math import comb


def pass_at_k(n, c, k):
    """P(at least one of k samples drawn without replacement succeeds)."""
    if not (0 <= c <= n) or not (1 <= k <= n):
        raise ValueError("need 0 <= c <= n and 1 <= k <= n")
    if n - c < k:          # every k-subset contains a success
        return 1.0
    return 1.0 - comb(n - c, k) / comb(n, k)


def pass_hat_k(n, c, k):
    """P(all k samples drawn without replacement succeed)."""
    if not (0 <= c <= n) or not (1 <= k <= n):
        raise ValueError("need 0 <= c <= n and 1 <= k <= n")
    return comb(c, k) / comb(n, k)   # comb(c, k) == 0 when c < k


def summarize(results, k):
    if not results:
        raise ValueError("no tasks")
    at, hat = [], []
    for task, trials in results.items():
        n, c = len(trials), sum(bool(t) for t in trials)
        at.append(pass_at_k(n, c, k))
        hat.append(pass_hat_k(n, c, k))
    return {"pass@k": sum(at) / len(at), "pass^k": sum(hat) / len(hat)}


if __name__ == "__main__":
    res = {"t1": [1, 1, 1, 0], "t2": [0, 0, 0, 0], "t3": [1, 1, 1, 1]}
    print(summarize(res, 2))   # pass@2 ~ 0.667, pass^2 ~ 0.5
